import * as React from "react";
import { ArrowRightIcon } from "lucide-react";

import { Badge } from "../ui/badge";
import { FieldError } from "../ui/field";
import { Icon, type IconName } from "../ui/icon";
import { Input, type InputProps } from "../ui/input";

import styles from "./field-mapping.module.css";

type FieldMappingSize = "sm" | "md" | "lg";

const FieldMappingContext = React.createContext<{ size: FieldMappingSize; targetHeader: string }>({
  size: "sm",
  targetHeader: "Value"
});

export type FieldMappingProps = {
  legend: string;
  sourceHeader: string;
  targetHeader: string;
  targetHint?: React.ReactNode;
  size?: FieldMappingSize;
  children: React.ReactNode;
};

export const FieldMapping = ({
  legend,
  sourceHeader,
  targetHeader,
  targetHint,
  size = "sm",
  children
}: FieldMappingProps) => {
  const context = React.useMemo(() => ({ size, targetHeader }), [size, targetHeader]);
  return (
    <fieldset className={styles.fieldMapping}>
      <legend className={styles.legend}>{legend}</legend>
      <div className={styles.grid} data-size={size}>
        <span className={styles.head}>{sourceHeader}</span>
        <span />
        <span className={styles.head}>
          {targetHeader}
          {targetHint}
        </span>
        <FieldMappingContext.Provider value={context}>{children}</FieldMappingContext.Provider>
      </div>
    </fieldset>
  );
};

export type FieldMappingRowProps = Omit<InputProps, "size" | "invalid"> & {
  source: string;
  icon?: IconName;
  error?: React.ReactNode;
} & { ref?: React.Ref<HTMLInputElement> };

export const FieldMappingRow = ({ source, icon, error, ...props }: FieldMappingRowProps) => {
  const { size, targetHeader } = React.useContext(FieldMappingContext);
  return (
    <div className={styles.row}>
      <span className={styles.source}>
        <Badge tone="soft" size={`control-${size}`}>
          {icon && <Icon name={icon} />}
          {source}
        </Badge>
      </span>
      <span className={styles.arrow} aria-hidden="true">
        <Icon icon={ArrowRightIcon} />
      </span>
      <div className={styles.target}>
        <Input
          aria-label={`${targetHeader} for ${source}`}
          {...props}
          size={size}
          invalid={Boolean(error)}
        />
        {error && <FieldError>{error}</FieldError>}
      </div>
    </div>
  );
};

.fieldMapping {
  min-width: 0;
  margin: 0;
  padding: 0;
  border: 0;
}
.legend {
  position: absolute;
  width: 1px;
  height: 1px;
  overflow: hidden;
  clip-path: inset(50%);
  white-space: nowrap;
}
.grid {
  --v4-field-mapping-height: var(--v4-size-control-sm);
  display: grid;
  grid-template-columns: auto var(--v4-size-icon) minmax(0, 1fr);
  gap: var(--v4-space-8) var(--v4-space-12);
  align-items: start;
}
.grid[data-size="md"] {
  --v4-field-mapping-height: var(--v4-size-control-md);
}
.grid[data-size="lg"] {
  --v4-field-mapping-height: var(--v4-size-control-lg);
}
.head {
  display: inline-flex;
  align-items: center;
  gap: var(--v4-space-4);
  color: var(--v4-muted);
  font-family: var(--v4-type-small-font-family);
  font-size: var(--v4-type-small-font-size);
  line-height: var(--v4-type-small-line-height);
}
.row {
  display: contents;
}
.source {
  display: flex;
  min-width: 0;
}
.source > [data-slot="badge"] {
  width: 100%;
  justify-content: flex-start;
}
.arrow {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  height: var(--v4-field-mapping-height);
  color: var(--v4-muted);
}
.target {
  display: flex;
  flex-direction: column;
  gap: var(--v4-space-field-label);
  min-width: 0;
}
